(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10 + Math.sin((x+y)*0.008+t*0.15)*8;
  const wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10 + Math.cos((x-y)*0.009-t*0.18)*8;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.7],
    [80+Math.sin(t*0.45+3)*110, 40+Math.cos(t*0.65+1)*60, 0.11, 2.1, 1.3],
    [400+Math.cos(t*0.55+2)*70, 200+Math.sin(t*0.75+4)*50, 0.05, 2.4, 0.85]
  ];
  let aS=0, iS=0, mS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave = Math.sin(d*f-t*sp);
    aS += wave*w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    mS += Math.sin(d*f*1.3-t*sp*0.4+2.8)*w*0.5;
  }
  const act=aS/8, inh=iS/8, mod=mS/8;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2 + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg2 = (Math.sin(sx*0.07-sy*0.05+t*1.3)+Math.cos(sx*0.05+sy*0.08-t*0.9))*0.3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2 = Math.sin(dist*0.03+ang*5-t*0.8)*Math.cos(dist*0.06-ang*2+t*1.1)*0.3;
  const voronoi = (() => {
    let mn = 99, mn2 = 99;
    for (let i=0; i<6; i++) {
      const px = (Math.sin(t*0.2+i*1.047)*180+240), py = (Math.cos(t*0.25+i*1.047)*100+120);
      const d = Math.sqrt((sx-px)**2+(sy-py)**2);
      if(d<mn){mn2=mn;mn=d;}else if(d<mn2)mn2=d;
    }
    return Math.sin((mn2-mn)*0.3)*0.4;
  })();
  const rd1 = Math.tanh((act - inh*0.7 + bg*0.3 + spiral)*2.2);
  const rd2 = Math.tanh((mod*1.5 - act*0.4 + bg2 + spiral2)*1.8);
  const coupled = Math.tanh((rd1*0.6 + rd2*0.4 + voronoi*0.3)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro = Math.sin(sx*0.3+t*3)*Math.sin(sy*0.25-t*2.5)*0.1;
  const blend = coupled*0.6 + cell*0.2 + micro*0.1 + (rd1*0.1);
  const v = blend*0.5+0.5;
  const pal = [[5,12,55],[12,55,95],[18,110,120],[45,165,135],[120,185,100],[195,185,60],[215,145,65],[200,95,60],[175,55,70],[120,30,60],[70,15,55],[25,10,50],[5,12,55]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.8+Math.sin(coupled*Math.PI)*0.2;
  const edge = Math.abs(coupled)>0.65?1.12:1.0;
  const glow = Math.max(0, coupled-0.3)*0.3;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + glow*40)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + glow*25)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + glow*15)|0)
  ];
}
